_LOOPBACK = ('127.0.0.1', 'localhost', '::1')
_GUARD = TransportSecuritySettings(enable_dns_rebinding_protection=True,
                                   allowed_hosts=['127.0.0.1:*', 'localhost:*', '[::1]:*'],
                                   allowed_origins=['http://127.0.0.1:*', 'http://localhost:*', 'http://[::1]:*'])

mcp = FastMCP('fossick', transport_security=_GUARD, instructions=(
    'Web toolkit. web_search/research for queries; fetch_page for URLs (heavy=JS, stealthy=anti-bot, '
    'session=logged-in Chrome, auto=escalate until not bot-blocked); read_arxiv/read_youtube/read_github_* '
    'for those sites; find_hidden_apis + replay_capture/paginate_api to turn a page into a JSON data feed; '
    'browse + page_* tools drive a persistent logged-in Chrome for interactive/authenticated flows; '
    'shop_* tools drive a shopping cart on any storefront — shop_open, shop_search, shop_add '
    '(verified: it tells you whether the cart actually changed), shop_cart, shop_fields/shop_fill '
    'for checkout forms.'))

#: The largest plain HTTP body a tool takes
MAX_BYTES = 20_000_000

def _on(var:str) -> bool: return (os.environ.get(var) or '').strip().lower() in ('1', 'true', 'yes', 'on')

#: Tools that use the logged-in debug Chrome are on only with FOSSICK_MCP_SESSION=1
SESSION = _on('FOSSICK_MCP_SESSION')
_live = mcp.tool() if SESSION else (lambda f: f)

def _need_session(used=True):
    "Raise `PermissionError` when a call uses the logged-in Chrome and `SESSION` is off."
    if used and not SESSION: raise PermissionError('logged-in Chrome tools are off: set FOSSICK_MCP_SESSION=1')

def _root() -> Path: return Path(os.environ.get('FOSSICK_MCP_ROOT') or os.getcwd()).resolve()

def _inroot(p) -> str:
    "`p` resolved against `_root()`, or `PermissionError` when it is outside."
    r = _root()
    q = (r/Path(p).expanduser()).resolve()
    if not q.is_relative_to(r): raise PermissionError(f'{p} is outside {r}: set FOSSICK_MCP_ROOT to change it')
    return str(q)

def _trunc(s, n):
    'Clip `s` to `n` chars with an explicit truncation marker.'
    s = s or ''
    return s if not n or len(s) <= n else s[:n] + f'\n…[truncated {len(s)-n} of {len(s)} chars]'

def _jsonable(o):
    'Recursively convert result objects (L, Response, Path, ...) to JSON-serializable types.'
    if isinstance(o, dict): return {str(k): _jsonable(v) for k, v in o.items()}
    if isinstance(o, (str, int, float, bool)) or o is None: return o
    if hasattr(o, '__iter__'): return [_jsonable(x) for x in o]
    return str(o)

